import sys

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    if not data: return
    N = int(data[0])
    x=[]; y=[]; p=[]
    idx=1
    for i in range(N):
        x.append(int(data[idx])); y.append(int(data[idx+1])); p.append(int(data[idx+2]))
        idx+=3
    def can(S):
        adj=[[] for _ in range(N)]
        for i in range(N):
            for j in range(N):
                if i==j: continue
                if p[i]*S >= abs(x[i]-x[j])+abs(y[i]-y[j]):
                    adj[i].append(j)
        for start in range(N):
            vis=[False]*N
            stack=[start]
            vis[start]=True
            while stack:
                u=stack.pop()
                for v in adj[u]:
                    if not vis[v]:
                        vis[v]=True
                        stack.append(v)
            if all(vis):
                return True
        return False
    lo=0; hi=2000000010
    while lo<hi:
        mid=(lo+hi)//2
        if can(mid): hi=mid
        else: lo=mid+1
    print(lo)

if __name__=='__main__':
    solve()

