void doing(){
    int n, k; cin >> n >> k;
    vector <int> adj[n + 7];
    for (int i = 0; i < n - 1; i++) {
        int a, b; cin >> a >> b;
        adj[a].push_back(b); adj[b].push_back(a);
    }
    vector <int> v(k); for (auto &i : v) cin >> i;
    vector <int> vis(n + 1), parent(n + 1), cp(n + 1);
    queue <int> q;
    q.push(v[0]);
    while (q.size()) {
        int node = q.front();
        q.pop();
        vis[node] = 1;
        for (auto it : adj[node]) {
            if (vis[it]) continue;
            q.push(it);
            parent[it] = node;
        }
    }
    ll ans = 0;
    cp[v[0]] = 1;
    for(int i = 0; i < k; i++) {
        int s = v[i];
        while (cp[s] == 0) {
            cp[s] = 1;
            s = parent[s];
        }
    }
    int s = 0;
    for (int i = 1; i <= n; i++) s += cp[i];
    cout << s;
} 

signed main(){
    ios_base::sync_with_stdio(false), cin.tie(nullptr), cout.tie(nullptr);
    int tc = 1;
    // cin >> tc;
