        int a,b; cin>>a>>b; g[a].push_back(b); g[b].push_back(a);
    }
    for(int i=0;i<k;i++){ int v; cin>>v; isk[v]=true; }
    dfs(1,0);
    cout<<ans<<endl;
    return 0;
}

